'use strict';
(() => {
 const FEATURES={tracker:false}; // programme tracker hidden for launch; set true to re-enable
 const $ = id => document.getElementById(id);
 const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let answers = {}, editing = false;
 let changeFilters={audience:'all',status:'all',query:'',sort:'relevance'};
 const region={type:'radios',name:'region',legend:'Where do you live?',hint:'Vaccination programmes vary across the UK. This prototype covers England only.',options:[{value:'England',label:'England'},{value:'Scotland',label:'Scotland'},{value:'Wales',label:'Wales'},{value:'Northern Ireland',label:'Northern Ireland'},{value:'Elsewhere',label:'Somewhere else'}],error:'Select where you live'};
 const screens={region,...Vaccs.SCREENS};
 const qLabels={region:'Country',...Vaccs.QUESTION_LABELS};
 function age(){return answers.dob ? Vaccs.ageAt(Vaccs.toDate(answers.dob),new Date()):null;}
 function flow(){
   const f=['region','who','dob'];
   if(age()!==null && age()<18)return [...f,'childRisk'];
   f.push('pregnancy');if(answers.pregnancy==='yes')f.push('weeks');
   f.push('immuno','conditions','work');
   if(age()!==null && age()>=18 && age()<25)f.push('student');
   return f;
 }
 function prune(){for(const k of Object.keys(answers)){if(!flow().includes(k))delete answers[k];}}
 function go(route){if(location.hash==='#'+route)render();else location.hash=route;}
 function main(content,title='Vaccination checker — Vaccs'){$('main').innerHTML=content;const route=location.hash.slice(1)||'home';document.querySelectorAll('.header nav a').forEach(a=>{const key=a.getAttribute('href').slice(1);const active=key==='changes'?route.startsWith('change'):key==='check'?['q/','review','results','check'].some(k=>route.startsWith(k)):route===key;if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=title;window.scrollTo(0,0);const h=$('main').querySelector('h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
 const button=(label,action,secondary=false)=>`<button class="btn ${secondary?'btn--secondary':''}" data-action="${action}">${label}</button>`;
 const back=(route,label='Back')=>`<a class="back" href="#${route}">← &nbsp;${label}</a>`;
 function home(){
 const upcoming=FEATURES.tracker?VaccsChanges.items[0]:null;
 main(`<div class="home-page"><section class="home-intro"><div class="home-main"><p class="eyebrow">Independent vaccination information · England</p><h1>Keep up with your vaccinations.</h1><p class="home-description">Find out which vaccinations to ask about.</p><div class="home-actions"><a class="btn" href="#check">Start a vaccination check <span aria-hidden="true">→</span></a>${FEATURES.tracker?`<a class="secondary-link" href="#changes">See what’s changed</a>`:'<a class="secondary-link" href="#about">How it works</a>'}</div><p class="home-duration">About 2 minutes · No account · Answers stay in this tab</p></div>${FEATURES.tracker?`<aside class="home-update"><div class="section-kicker">Confirmed programme date</div><div class="feature-date"><span>01</span><div>November<br>2026</div></div><h2>${esc(upcoming.title)}</h2><p>${esc(upcoming.summary)}</p><a href="#changes/${upcoming.id}">Who this affects <span aria-hidden="true">→</span></a></aside>`:`<aside class="home-update"><div class="section-kicker">What this does</div><h2>A list of vaccinations to ask about</h2><p>Answer a few questions and get topics to raise with a GP surgery, pharmacist or midwife. It does not confirm eligibility.</p><a href="#about">How it works <span aria-hidden="true">→</span></a></aside>`}</section>${FEATURES.tracker?`<section class="home-latest" aria-labelledby="latest-title"><div class="section-heading"><div><p class="eyebrow">Programme tracker</p><h2 id="latest-title">Changes worth knowing about</h2></div><a href="#changes">View all updates <span aria-hidden="true">→</span></a></div><div class="home-update-grid">${[VaccsChanges.items[1],VaccsChanges.items[2],VaccsChanges.items[4]].map(i=>`<article class="update-preview"><div class="preview-meta">${badge(i)}<span>${esc(i.vaccine)}</span></div><h3><a href="#changes/${i.id}">${esc(i.title)}</a></h3><p>${esc(i.summary)}</p><a class="preview-link" href="#changes/${i.id}">Read update <span aria-hidden="true">→</span></a></article>`).join('')}</div><p class="section-footnote">Selected updates · Sources checked ${dateLabel(VaccsChanges.meta.checkedOn)} · <a href="#sources">How we use sources</a></p></section>`:''}<section class="home-prepare"><div><p class="eyebrow">Using the checker</p><h2>Before you start</h2><p>You can check for yourself or someone else. Have their date of birth to hand.</p><a href="#check">Start the check →</a></div><div class="home-details"><details><summary>What will the results tell me?</summary><p>You’ll see vaccinations to discuss, why they appeared and links to official guidance. The results cannot confirm eligibility or whether a course is complete.</p></details><details><summary>Do I need my vaccination record?</summary><p>No. You do not need it to use the checker. A health professional will need the record to confirm what, if anything, you need.</p></details><details><summary>What about children and travel?</summary><p>For children, the checker links to the official schedule. It does not calculate dose dates or cover travel vaccinations.</p></details></div></section><div class="home-disclaimer"><strong>Independent prototype. This information has not been clinically reviewed.</strong><p>Vaccs is not an NHS service. Confirm advice with a qualified health professional.</p></div></div>`,'Vaccs — vaccination information');
 }
 function aside(stage){return `<aside class="journey-aside"><h2 class="aside-title">Your check</h2><ol class="journey-steps">${['The basics','Your circumstances','Your summary'].map((s,i)=>`<li class="${i===stage?'active':i<stage?'complete':''}" ${i===stage?'aria-current="step"':''}><span class="step-bubble">${i<stage?'✓':i+1}</span><span>${s}</span></li>`).join('')}</ol><div class="aside-privacy"><strong><span class="lock" aria-hidden="true"></span> Your answers stay here</strong>Answers are held in memory. Refreshing or closing the page clears them.<a href="#privacy">Privacy information</a></div></aside>`;}
 function panel(content,stage=0){return `<div class="checker-layout">${aside(stage)}<section class="question-panel">${content}</section></div>`;}
 function getOptions(id){return (screens[id].options||[]).filter(o=>!o.showIf||o.showIf(answers));}
 function titleFor(s){return answers.who==='self' && s.legendSelf ? s.legendSelf:s.legend;}
 function question(id,error){
   const s=screens[id], f=flow(), index=f.indexOf(id), stage=index<3?0:1;
   const value=answers[s.name];
   const previous=index>0?'q/'+f[index-1]:'home';
   let fields='';
   const hint=s.hint?`<p class="hint" id="question-hint">${esc(s.hint)}</p>`:'';
   const help=s.details?`<details><summary>${esc(s.details.summary)}</summary><div class="details-body">${s.details.html}</div></details>`:'';
   const input=(o,none=false)=>`<div class="option"><input id="${id}-${o.value}" name="${id}" value="${esc(o.value)}" type="${s.type==='checkboxes'?'checkbox':'radio'}" ${Array.isArray(value)?value.includes(o.value)?'checked':'':value===o.value?'checked':''}><label for="${id}-${o.value}">${esc(o.label)}${o.hint?`<span class="option-hint">${esc(o.hint)}</span>`:''}</label></div>`;
   if(s.type==='radios'||s.type==='checkboxes')fields=help+getOptions(id).map(o=>input(o)).join('')+(s.noneOption?`<p class="option-divider">or</p>${input(s.noneOption,true)}`:'');
   if(s.type==='date'){
     const [y,m,d]=(value||'--').split('-');
     fields=`<div class="date-parts"><div><label for="dob-day">Day</label><input class="input" id="dob-day" name="day" inputmode="numeric" maxlength="2" value="${esc(d)}" autocomplete="off"></div><div><label for="dob-month">Month</label><input class="input" id="dob-month" name="month" inputmode="numeric" maxlength="2" value="${esc(m)}" autocomplete="off"></div><div class="year"><label for="dob-year">Year</label><input class="input" id="dob-year" name="year" inputmode="numeric" maxlength="4" value="${esc(y)}" autocomplete="off"></div></div>`;
   }
   if(s.type==='number')fields=`<label class="field-label" for="weeks">${esc(s.label)}</label><input class="input" id="weeks" name="weeks" inputmode="numeric" maxlength="2" value="${esc(value)}" aria-describedby="question-hint">`;
   const first=s.type==='date'?'dob-day':s.type==='number'?'weeks':`${id}-${getOptions(id)[0].value}`;
   main(panel(`${back(previous)}<div class="eyebrow">${stage===0?'01 / The basics':'02 / Your circumstances'}</div>${error?`<div class="error-summary" id="error-summary" role="alert" tabindex="-1"><strong>Check your answer</strong><a href="#${first}" data-focus="${first}">${esc(error)}</a></div>`:''}<form data-question="${id}" novalidate><fieldset ${s.hint?'aria-describedby="question-hint"':''}><legend><span role="heading" aria-level="1">${esc(titleFor(s))}</span></legend>${hint}${fields}</fieldset><button class="btn" type="submit">Continue <span aria-hidden="true">→</span></button></form><div class="question-footer"><span>${s.type==='checkboxes'?'Select all that apply':''}</span><button class="text-button" data-action="reset">Clear &amp; start again</button></div>`,stage),`${titleFor(s)} — Vaccs`);
   if(error)$('error-summary').focus();else{const firstHeading=$('main').querySelector('legend');firstHeading.tabIndex=-1;firstHeading.focus({preventScroll:true});}
 }
 function readAnswer(id,form){
   const s=screens[id],data=new FormData(form);
   if(s.type==='radios'){const value=data.get(id);return value?{value}:{error:s.error};}
   if(s.type==='checkboxes'){const value=data.getAll(id);return value.length?{value}:{error:s.error};}
   if(s.type==='date'){
     const ds=data.get('day').trim(),ms=data.get('month').trim(),ys=data.get('year').trim();
     if(!ds||!ms||!ys)return {error:'Enter a complete date of birth: day, month and year.'};
     if(!/^\d{1,2}$/.test(ds)||!/^\d{1,2}$/.test(ms)||!/^\d{4}$/.test(ys)||!Vaccs.isValidDate(+ys,+ms,+ds))return {error:'Enter a real date of birth, with a four-digit year.'};
     const dt=new Date(+ys,+ms-1,+ds), now=new Date();
     if(dt>now||Vaccs.ageAt(dt,now)>120)return {error:'Enter a date of birth in the past, within the last 120 years.'};
     return {value:`${ys}-${ms.padStart(2,'0')}-${ds.padStart(2,'0')}`};
   }
   const v=data.get('weeks').trim();
   if(!/^\d+$/.test(v)||+v<1||+v>42)return {error:'Enter a whole number of weeks between 1 and 42.'};
   return {value:+v};
 }
 function submit(form){
   const id=form.dataset.question,r=readAnswer(id,form);
   if(r.error)return question(id,r.error);
   answers[id]=r.value;prune();
   if(id==='region'&&r.value!=='England'){go('outside');return;}
   const f=flow(),next=f[f.indexOf(id)+1];
   if(editing){const missing=f.find(k=>answers[k]===undefined);if(missing){go('q/'+missing);return;}editing=false;go('review');return;}
   go(next?'q/'+next:'review');
 }
 function answerText(id){
   const v=answers[id],s=screens[id];
   if(id==='dob')return `${Vaccs.fmtDate(Vaccs.toDate(v))} (age ${age()})`;
   const options=[...getOptions(id),...(s.noneOption?[s.noneOption]:[])];
   if(Array.isArray(v))return v.map(x=>options.find(o=>o.value===x)?.label||x).join(', ');
   if(s.options)return options.find(o=>o.value===v)?.label||v;
   return `${v} weeks`;
 }
 function review(){main(panel(`${back('q/'+flow().at(-1))}<div class="eyebrow">03 / Your summary</div><h1>Check your answers</h1><p class="hint">Take a moment to check the answers. You can change anything before seeing the results.</p><ul class="summary-list">${flow().map(id=>`<li class="summary-row"><span class="summary-key">${esc(qLabels[id])}</span><span class="summary-val">${esc(answerText(id))}</span><button class="text-button summary-act" data-edit="${id}" aria-label="Change ${esc(qLabels[id])}">Change</button></li>`).join('')}</ul><div class="notice"><strong>Before you continue</strong><p>This is a discussion list, not confirmation of eligibility or a check against your medical record.</p></div><a class="btn" href="#results">See my results <span aria-hidden="true">→</span></a><div class="question-footer"><span>Answers stay in this tab</span><button class="text-button" data-action="reset">Clear &amp; start again</button></div>`,2),'Check your answers — Vaccs');}
 function routeFor(c){if(c.ruleIds.some(id=>id.startsWith('work-')))return 'Ask your employer’s occupational health service about vaccination for your role.';if(['fluPreg','wcough','rsvPreg'].includes(c.key))return 'Discuss this with a midwife, GP surgery or maternity vaccination team.';return 'Use the official guidance to check who it is offered to and how to arrange it.';}
 function results(){
   const result=Vaccs.assess(answers), count=result.cards.length;
   main(`<div class="result-wrap">${back('review','Review answers')}<div class="result-top"><div><div class="eyebrow">Your results</div><h1>Vaccinations to ask about</h1><p class="hint">${count?`${count} vaccination ${count===1?'topic':'topics'} to explore based on the answers given.`:'No specific vaccination topics were flagged by these answers.'} A health professional can confirm what applies.</p></div><div class="result-actions">${button('Save or print','print',true)}${button('Start again','reset',true)}</div></div><div class="notice notice--warm"><strong>This checker has not been clinically reviewed.</strong><p>This prototype has not been clinically approved. It does not confirm that a vaccine is due, suitable or available, and cannot tell whether a course is complete.</p></div><div class="result-meta"><span>England</span><span>Generated ${esc(Vaccs.fmtDate(new Date()))}</span><span>Rules v${esc(result.version)}</span><span>Not clinically reviewed</span></div><div class="print-only print-notice"><strong>Vaccs · Independent design prototype · Not an NHS service</strong><br>This list may be incomplete or wrong. It is not connected to a vaccination record. Confirm every item with a qualified health professional. This checker has not been clinically reviewed; this is not clinical advice.</div><div class="notice"><strong>Not seeing a vaccine here does not mean you do not need it.</strong><p>This list covers a limited set of situations. Ask a health professional to check your full record.</p></div>${count?`<div class="results-grid">${result.cards.map((c,i)=>`<article class="result-card"><h2>${esc(c.name)}</h2><ul>${c.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul><div class="card-route"><strong>Next step</strong>${esc(routeFor(c))}</div><a class="card-link" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Read NHS guidance <span aria-hidden="true">↗</span><span class="sr-only"> (opens in a new tab)</span></a><details class="card-evidence"><summary>Why this is on the list</summary><p>Triggered rules: ${c.ruleIds.map(esc).join(', ')}.</p><p>Source: NHS public guidance. Detailed source-section mapping is incomplete. This checker has not been clinically reviewed. Version ${esc(result.version)}.</p></details></article>`).join('')}</div>`:`<div class="empty-state"><h2>No specific results</h2><p class="hint">This checker covers a limited set of situations. It cannot confirm that the routine schedule is complete.</p><a href="https://www.nhs.uk/vaccinations/nhs-vaccinations-and-when-to-have-them/" target="_blank" rel="noopener noreferrer">Check the routine vaccination schedule ↗</a></div>`}<section class="result-notes"><h2>What else to check</h2><ul>${result.notes.map(n=>`<li>${esc(n)}</li>`).join('')}<li>Travel vaccinations are not covered. Speak to a travel health service about destination-specific advice.</li><li>Previous doses, allergies, treatment and individual circumstances can change the advice. Bring the vaccination record if available.</li></ul></section>${FEATURES.tracker?`<div class="results-tracker-link no-print"><div><h2>Check programme changes</h2><p>New offers and future recommendations may be relevant to this list.</p></div><a href="#changes">View vaccination updates →</a></div>`:''}<div class="bottom-note"><h3>Who to speak to</h3><p>A GP surgery, pharmacist, midwife or vaccination team can help confirm what applies.</p><a href="#sources">View sources</a></div></div>`,'Your vaccination discussion list — Vaccs');
 }
 function outside(){const links={Scotland:'https://www.nhsinform.scot/healthy-living/immunisation/',Wales:'https://phw.nhs.wales/topics/immunisation-and-vaccines/','Northern Ireland':'https://www.nidirect.gov.uk/articles/immunisation'};main(panel(`${back('q/region')}<div class="eyebrow">Location</div><h1>This checker covers England</h1><p class="hint">This prototype uses England-focused guidance. It should not apply those rules to ${esc(answers.region||'another country')}.</p><a class="btn" href="${links[answers.region]||'https://www.who.int/health-topics/vaccines-and-immunization'}" target="_blank" rel="noopener noreferrer">Find local guidance <span aria-hidden="true">↗</span></a><div class="notice">Check your local health service for vaccination eligibility and availability.</div>`,0),'Find local vaccination guidance — Vaccs');}
 function about(){main(`<article class="content-page">${back('home','Home')}<div class="eyebrow">About</div><h1>About the checker</h1><p class="lead">Vaccs is an independent design prototype exploring a simpler way to understand vaccination guidance.</p><h2>How it works</h2><ol><li>Answer a short set of questions about age, health and circumstances.</li><li>A fixed set of rules matches those answers to possible vaccination topics. There is no generative AI making health recommendations.</li><li>See why each topic appeared, read the linked official guidance, and discuss it with a qualified health professional.</li></ol><h2>What it can’t tell you</h2><p>It cannot confirm eligibility, clinical suitability, dose timing, booking availability or whether you have already completed a course. It has no access to your medical or vaccination record.</p><p>For children, it provides schedule and risk-review signposting. It does not calculate individual dose dates or catch-up plans. Travel vaccinations are outside its scope.</p><div class="notice notice--warm"><strong>This checker has not been clinically reviewed.</strong><p>The rules are a prototype interpretation of published information. They may be incomplete, outdated or wrong. Links to NHS or government guidance do not mean endorsement.</p></div>${FEATURES.tracker?`<h2>Following programme changes</h2><p>The <a href="#changes">changes tracker</a> explains selected updates from official sources. It separates recommendations, confirmed starts and changes already introduced. Every entry includes a source and the date it was checked.</p>`:''}<h2>Something doesn’t look right?</h2><p>Use the official guidance and speak to a health professional. To report a prototype issue, open an issue in the project repository. Do not post a date of birth, medical history or anyone’s personal details.</p><a href="https://github.com/stephenocall30/vaccs-checker/issues" target="_blank" rel="noopener noreferrer">Report a technical or content issue ↗</a><h2>Independent project</h2><p>Vaccs is not an NHS service and is not affiliated with, commissioned by or approved by the NHS, UKHSA or JCVI.</p><a class="btn" href="#check">Start the check <span aria-hidden="true">↗</span></a></article>`,'About this prototype — Vaccs');}
 function privacy(){main(`<article class="content-page">${back(answers.dob?'review':'home',answers.dob?'Back to your answers':'Home')}<div class="eyebrow">Your privacy</div><h1>Your privacy</h1><p class="lead">The checker keeps your answers in this tab. It does not save them to an account or include them in links.</p><h2>What happens to your answers?</h2><p>The checker holds your answers in this page’s memory while you use it. It does not send those answers to a server or put them in URLs, cookies, local storage or session storage. Refreshing, closing the page or choosing “Clear &amp; start again” clears the application’s answers.</p><p>Navigation within the page keeps answers available until you clear them. Do not leave an open session on a shared device. Your browser may independently offer form autofill or restore a suspended tab.</p><h2>What about the website itself?</h2><p>Like other hosted websites, the hosting provider may process technical access information such as IP address and browser details. Access controls for this private preview may also use your signed-in account. That is separate from the checker’s health answers.</p><p>This build does not include advertising, analytics, third-party fonts or session replay. Its clinical rules run in your browser.</p><h2>Printing and external links</h2><p>If you save or print your results, that copy contains health-related discussion topics. Store and share it carefully. We do not upload or email it.</p><p>Official guidance links open a separate website with its own privacy policy. Your checker answers are not included in those links.</p><div class="notice"><strong>A prototype privacy explanation, not a completed launch notice.</strong><p>Before public launch, the operator must identify themselves, provide a contact route and confirm the hosting arrangements, lawful basis and other applicable privacy obligations.</p></div>${button('Clear my answers','reset',true)}</article>`,'Your privacy — Vaccs');}
 function sources(){const v=Vaccs.META;main(`<article class="content-page">${back('home','Home')}<div class="eyebrow">Our approach</div><h1>Sources and review</h1><p class="lead">We summarise published guidance from UKHSA, JCVI and the NHS, with links so you can check the original information.</p><div class="source-status">${FEATURES.tracker?`<div><strong>Changes tracker</strong>Source check: ${dateLabel(VaccsChanges.meta.checkedOn)}</div>`:''}<div><strong>Checker rules v${esc(v.version)}</strong>This information has not been clinically reviewed</div></div>${FEATURES.tracker?`<h2>What the status labels mean</h2><dl class="status-definitions"><div><dt>${badge({status:'started'})}</dt><dd>The published programme has been introduced, based on the sources and dates checked.</dd></div><div><dt>${badge({status:'confirmed'})}</dt><dd>A programme start is confirmed in official guidance. This does not mean appointments are open.</dd></div><div><dt>${badge({status:'advice'})}</dt><dd>JCVI has published a recommendation. The entry does not confirm implementation or availability.</dd></div></dl><h2>Keeping information current</h2><p>Each update includes its source, affected group, dates and a record of edits. Changes are selected and checked manually; this is not an exhaustive or live news feed.</p><p>A source check confirms what the cited publication says. It is not clinical approval. Programme updates do not automatically change the checker’s rules.</p><p>When a review is overdue, an entry asks you to check the official source. Dates alone never turn a recommendation into an active programme.</p><h2>Tracker references</h2>${[...new Map(VaccsChanges.items.map(i=>[i.sourceUrl,i])).values()].map(i=>`<div class="source-row"><div><h3>${esc(i.sourceTitle)}</h3><p>Source checked ${dateLabel(VaccsChanges.meta.checkedOn)}</p></div><a href="${esc(i.sourceUrl)}" target="_blank" rel="noopener noreferrer">Read source ↗<span class="sr-only"> (opens in a new tab)</span></a></div>`).join('')}`:`<h2>Keeping information current</h2><p>A source check confirms what a cited publication says. It is not clinical approval. Programme updates do not automatically change the checker’s rules.</p>`}<h2>Checker references</h2>${Vaccs.SOURCE_REGISTER.filter(i=>['schedule','greenbook','jcvi','updates','flu','shingles','rsv','covid','mmr'].includes(i.id)).map(i=>`<div class="source-row"><div><h3>${esc(i.title)}</h3><p>This checker has not been clinically reviewed</p></div><a href="${esc(i.url)}" target="_blank" rel="noopener noreferrer">Read source ↗<span class="sr-only"> (opens in a new tab)</span></a></div>`).join('')}<div class="notice"><strong>Found an error?</strong><p><a href="https://github.com/stephenocall30/vaccs-checker/issues" target="_blank" rel="noopener noreferrer">Report a problem with the prototype</a>. Do not include personal or medical details.</p></div><p class="attribution">Contains public sector information licensed under the <a href="https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/" target="_blank" rel="noopener noreferrer">Open Government Licence v3.0</a>. No official endorsement is implied.</p></article>`,'Sources and review — Vaccs');}
 function dateLabel(iso){return Vaccs.fmtDate(Vaccs.toDate(iso));}
 function badge(item){return `<span class="status-badge status-${esc(item.status)}">${esc(VaccsChanges.statuses[item.status])}</span>`;}
 function updateRow(i){return `<article class="change-row"><div class="change-row-meta">${badge(i)}<span class="change-vaccine">${esc(i.vaccine)}</span><span>${esc(i.timing)}</span></div><div class="change-row-body"><h2><a href="#changes/${i.id}">${esc(i.title)}</a></h2><p>${esc(i.summary)}</p><div class="audience-label">${i.audiences.map(a=>esc(VaccsChanges.audiences[a])).join(' · ')}</div></div><a class="row-arrow" href="#changes/${i.id}" aria-label="Read update: ${esc(i.title)}">→</a></article>`;}
 function changeList(){
   const found=VaccsChanges.filter(changeFilters);
   $('change-results').innerHTML=found.length?found.map(updateRow).join(''):`<div class="empty-state"><h2>No updates match these filters</h2><p>This is a selected set of programme changes, not a full list of vaccination guidance.</p><button class="text-button" data-action="clear-filters">Clear filters</button>${changeFilters.audience==='pregnancy'?'<p><a href="https://www.nhs.uk/vaccinations/" target="_blank" rel="noopener noreferrer">Read current NHS vaccination guidance ↗</a></p>':''}</div>`;
   $('change-count').textContent=`${found.length} ${found.length===1?'update':'updates'}`;
 }
 function changes(){
   main(`<div class="changes-page"><div class="page-intro"><p class="eyebrow">Programme tracker · England</p><h1>What’s changed?</h1><p>Changes to vaccination guidance, who they affect and what to do next.</p></div><div class="tracker-meta"><span>Sources checked ${dateLabel(VaccsChanges.meta.checkedOn)}</span><a href="#sources">About these updates</a></div><section class="change-controls" aria-label="Filter vaccination updates"><fieldset class="audience-filter"><legend>Show updates for</legend><div>${Object.entries(VaccsChanges.audiences).map(([k,v])=>`<button type="button" data-audience="${k}" aria-pressed="${changeFilters.audience===k}">${esc(v)}</button>`).join('')}</div></fieldset><div class="filter-fields"><div class="search-field"><label for="change-search">Search updates</label><input id="change-search" type="search" placeholder="Try MMRV or shingles" value="${esc(changeFilters.query)}" autocomplete="off"></div><div><label for="change-status">Status</label><select id="change-status">${Object.entries(VaccsChanges.statuses).map(([k,v])=>`<option value="${k}" ${changeFilters.status===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div><label for="change-sort">Sort by</label><select id="change-sort"><option value="relevance" ${changeFilters.sort==='relevance'?'selected':''}>Upcoming first</option><option value="announced" ${changeFilters.sort==='announced'?'selected':''}>Announcement date</option></select></div></div></section><div class="list-heading"><p id="change-count" role="status" aria-live="polite"></p><button class="text-button" data-action="clear-filters">Clear filters</button></div><div id="change-results"></div><div class="tracker-explainer"><h2>Recommendation or programme?</h2><p>A recommendation can come before a confirmed programme. Check the status and effective date before acting on an update.</p><a href="#sources">How we label changes →</a></div><p class="section-footnote">Selected updates, checked manually. This information has not been clinically reviewed. Always confirm the current position using the official source.</p></div>`,'Vaccination changes — Vaccs');
   changeList();
 }
 function changeDetail(id){
   const i=VaccsChanges.items.find(i=>i.id===id);
   if(!i){main(`<article class="content-page">${back('changes','All updates')}<h1>Update not found</h1><p>This link does not match an update in the tracker.</p></article>`,'Update not found — Vaccs');return;}
   const siblings=VaccsChanges.items.filter(o=>o.id!==i.id && o.audiences.some(a=>i.audiences.includes(a))).slice(0,2);
   main(`<article class="update-detail">${back('changes','All updates')}<div class="detail-topline">${badge(i)}<span>${esc(i.vaccine)} · England</span></div><h1>${esc(i.title)}</h1><p class="lead">${esc(i.summary)}</p><dl class="update-facts"><div><dt>${i.status==='advice'?'Proposed timing':'Programme timing'}</dt><dd>${esc(i.timing)}</dd></div><div><dt>Announcement</dt><dd>${dateLabel(i.announcedOn)}</dd></div><div><dt>Source checked</dt><dd>${dateLabel(VaccsChanges.meta.checkedOn)}</dd></div></dl><section class="affected-block"><h2>Who this affects</h2><p>${esc(i.affects)}</p></section><section class="change-comparison" aria-label="What changed"><div><h2>Previously</h2><p>${esc(i.before)}</p></div><div><h2>${i.status==='advice'?'The recommendation':'The change'}</h2><p>${esc(i.after)}</p></div></section><section class="next-step"><span class="next-step-mark" aria-hidden="true">→</span><div><h2>What to do next</h2><p>${esc(i.next)}</p></div></section><p class="detail-caveat">${esc(VaccsChanges.statusNote(i))}</p><section class="detail-source"><h2>Official source</h2><a href="${esc(i.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(i.sourceTitle)} ↗<span class="sr-only"> (opens in a new tab)</span></a><p>${esc(i.sourceSection)}</p><span>Source checked ${dateLabel(VaccsChanges.meta.checkedOn)} · Not clinically reviewed</span></section><details class="edit-history"><summary>Update history</summary><ul>${i.editorialHistory.map(h=>`<li><time datetime="${h.date}">${dateLabel(h.date)}</time><p>${esc(h.text)}</p></li>`).join('')}</ul><p>Related checker rules: ${i.ruleLinks.map(esc).join(', ')}. Publishing this update does not change those rules.</p></details><div class="detail-actions"><a class="btn" href="#check">Start a vaccination check →</a><a href="#changes">Back to all updates</a></div>${siblings.length?`<section class="related-updates"><h2>Related updates</h2>${siblings.map(o=>`<a href="#changes/${o.id}">${esc(o.title)} <span aria-hidden="true">→</span></a>`).join('')}</section>`:''}</article>`,'Vaccs — '+i.title);
 }
 function render(){
   const route=location.hash.slice(1)||'home';
   if(FEATURES.tracker){if(route==='changes')return changes();if(route.startsWith('changes/'))return changeDetail(route.slice(8));}
   if(route==='home')return home();if(route==='about')return about();if(route==='privacy')return privacy();if(route==='sources')return sources();
   if(route==='check'){if(answers.region && answers.region!=='England')return go('outside');const next=flow().find(k=>answers[k]===undefined);return go(next?'q/'+next:'review');}
   if(route==='outside')return outside();
   if(route.startsWith('q/')){const id=route.slice(2);if(id!=='region' && answers.region && answers.region!=='England')return go('outside');if(!screens[id]||!flow().includes(id))return go('check');const before=flow().slice(0,flow().indexOf(id)).find(k=>answers[k]===undefined);if(before)return go('q/'+before);return question(id);}
   if(route==='review'||route==='results'){if(answers.region && answers.region!=='England')return go('outside');const missing=flow().find(k=>answers[k]===undefined);if(missing)return go('q/'+missing);return route==='review'?review():results();}
   go('home');
 }
 document.addEventListener('submit',e=>{if(e.target.matches('[data-question]')){e.preventDefault();submit(e.target);}});
 document.addEventListener('input',e=>{if(e.target.id==='change-search'){changeFilters.query=e.target.value;changeList();}});
 document.addEventListener('change',e=>{if(e.target.id==='change-status'||e.target.id==='change-sort'){changeFilters[e.target.id==='change-status'?'status':'sort']=e.target.value;changeList();return;}if(e.target.type!=='checkbox')return;const inputs=[...document.querySelectorAll(`input[name="${e.target.name}"]`)];if(e.target.checked){if(e.target.value==='none')inputs.forEach(i=>{if(i!==e.target)i.checked=false});else inputs.forEach(i=>{if(i.value==='none')i.checked=false;});}});
 document.addEventListener('click',e=>{
   const audience=e.target.closest('[data-audience]');if(audience){changeFilters.audience=audience.dataset.audience;document.querySelectorAll('[data-audience]').forEach(b=>b.setAttribute('aria-pressed',String(b===audience)));changeList();return;}
   if(e.target.closest('[data-action="clear-filters"]')){changeFilters={audience:'all',status:'all',query:'',sort:'relevance'};changes();$('change-search').focus();return;}
   const f=e.target.closest('[data-focus]');if(f){e.preventDefault();$(f.dataset.focus)?.focus();return;}
   const edit=e.target.closest('[data-edit]');if(edit){editing=true;go('q/'+edit.dataset.edit);return;}
   const b=e.target.closest('[data-action]');if(!b)return;
   if(b.dataset.action==='reset'){answers={};editing=false;history.replaceState(null,'',location.pathname+location.search+'#home');home();}
   if(b.dataset.action==='print')window.print();
 });
 window.addEventListener('hashchange',render);
 // Never hydrate answers from a URL, even when arriving from the original prototype.
 render();
})();
